from pathlib import Path
import json, re

root = Path(__file__).resolve().parents[1]

# Version metadata
pkg = root / 'package.json'
p = json.loads(pkg.read_text())
p['version'] = '1.0.0-rc.9.16'
p['description'] = 'Qanteak OS RC9 V0.16 sheet editor, lifecycle actions and permissions polish'
pkg.write_text(json.dumps(p, indent=2) + '\n')

lock = root / 'package-lock.json'
s = lock.read_text()
s = s.replace('"version": "1.0.0-rc.9.15"', '"version": "1.0.0-rc.9.16"', 2)
